package io.github.ningpp.compat;

import java.util.Arrays;

/**
 * Lightweight array-slice container (generated by CSharpToJava converter).
 * Does not simulate C# ref-struct lifetime semantics.
 */
public final class Span<T> {
    private final Object array;
    private final int offset;
    private final int length;
    /**
     * True when this span is a 4-byte little-endian int view over a byte[] backing
     * (C# {@code MemoryMarshal.Cast<byte, int>}). Element {@code i} then covers bytes
     * {@code 4i..4i+3} instead of the single byte the byte-backed span addresses.
     */
    private final boolean int32View;

    /** Default (empty) span — mirrors default(Span&lt;T&gt;). */
    public Span() {
        this.array = null;
        this.offset = 0;
        this.length = 0;
        this.int32View = false;
    }

    public Span(T[] array) {
        this.array = array;
        this.offset = 0;
        this.length = array.length;
        this.int32View = false;
    }

    public Span(byte[] array) {
        this.array = array;
        this.offset = 0;
        this.length = array.length;
        this.int32View = false;
    }

    public Span(char[] array) {
        this.array = array;
        this.offset = 0;
        this.length = array.length;
        this.int32View = false;
    }

    /** Copy constructor — allows wrapping an existing ReadOnlySpan without type inference issues */
    public Span(ReadOnlySpan<T> other) {
        this.array = other.getArray() != null ? other.getArray() : other.toArray();
        this.offset = other.getArray() != null ? other.getOffset() : 0;
        this.length = other.getLength();
        this.int32View = false;
    }

    /** Internal view constructor used by {@link #castToInt32(Span)}. */
    private Span(Object array, int offset, int elementCount, boolean int32View) {
        this.array = array;
        this.offset = offset;
        this.length = elementCount;
        this.int32View = int32View;
    }

    /**
     * Mirrors C# {@code MemoryMarshal.Cast<byte, int>(Span<byte>)}: a 4-byte
     * little-endian int view over the same backing bytes. Writes through the view
     * reach the original array, which is what callers such as
     * {@code JsonDocument.MetadataDb.CopySegment} rely on when they nudge the row
     * location fields. A span that is not byte-backed is already element-typed and
     * is returned unchanged.
     */
    public static Span<Integer> castToInt32(Span<Integer> span) {
        if (span == null) {
            return new Span<>();
        }
        Object backing = span.array;
        if (backing instanceof byte[] bytes) {
            return new Span<Integer>(bytes, span.offset, span.length / 4, true);
        }
        return span;
    }

    /** Mirrors C# Span&lt;T&gt; → ReadOnlySpan&lt;T&gt; implicit conversion. */
    public ReadOnlySpan<T> asReadOnlySpan() {
        return new ReadOnlySpan<>(this);
    }

    public Span(T[] array, int offset, int length) {
        if (offset < 0 || length < 0 || offset + length > array.length) {
            throw new IndexOutOfBoundsException(
                "offset=" + offset + ", length=" + length + ", arrayLength=" + array.length);
        }
        this.array = array;
        this.offset = offset;
        this.length = length;
        this.int32View = false;
    }

    public Span(byte[] array, int offset, int length) {
        if (offset < 0 || length < 0 || offset + length > array.length) {
            throw new IndexOutOfBoundsException(
                "offset=" + offset + ", length=" + length + ", arrayLength=" + array.length);
        }
        this.array = array;
        this.offset = offset;
        this.length = length;
        this.int32View = false;
    }

    public Span(char[] array, int offset, int length) {
        if (offset < 0 || length < 0 || offset + length > array.length) {
            throw new IndexOutOfBoundsException(
                "offset=" + offset + ", length=" + length + ", arrayLength=" + array.length);
        }
        this.array = array;
        this.offset = offset;
        this.length = length;
        this.int32View = false;
    }

    public int length() {
        return length;
    }

    /** Alias of {@link #length()} matching C# Span&lt;T&gt;.Length property access. */
    public int getLength() {
        return length;
    }

    /**
     * Mirrors C# Span&lt;T&gt;.TryCopyTo(Span&lt;T&gt;): copies elements into the
     * destination array; returns false when the destination is too short.
     */
    public boolean tryCopyTo(T[] destination) {
        if (destination == null) {
            throw new NullPointerException("destination");
        }
        if (destination.length < length) {
            return false;
        }
        for (int i = 0; i < length; i++) {
            destination[i] = get(i);
        }
        return true;
    }

    /**
     * Mirrors C# Span&lt;T&gt;.TryCopyTo(Span&lt;T&gt;): copies into the destination
     * span; returns false when the destination is too short.
     */
    public boolean tryCopyTo(Span<T> destination) {
        if (destination == null) {
            throw new NullPointerException("destination");
        }
        if (destination.length < length) {
            return false;
        }
        for (int i = 0; i < length; i++) {
            destination.set(i, get(i));
        }
        return true;
    }

    /** Raw backing array (byte[], char[], or T[]) — lets erased call sites adapt writes. */
    public Object getBackingArray() {
        return array;
    }

    public T get(int index) {
        if (index < 0 || index >= length) {
            throw new IndexOutOfBoundsException("index=" + index + ", length=" + length);
        }
        if (array instanceof byte[] bytes) {
            if (int32View) {
                @SuppressWarnings("unchecked")
                T value = (T) java.lang.Integer.valueOf(readInt32(bytes, offset + index * 4));
                return value;
            }
            @SuppressWarnings("unchecked")
            T value = (T) java.lang.Integer.valueOf(bytes[offset + index] & 0xFF);
            return value;
        }
        if (array instanceof char[] chars) {
            @SuppressWarnings("unchecked")
            T value = (T) Character.valueOf(chars[offset + index]);
            return value;
        }
        @SuppressWarnings("unchecked")
        T value = ((T[]) array)[offset + index];
        return value;
    }

    public void set(int index, T value) {
        if (index < 0 || index >= length) {
            throw new IndexOutOfBoundsException("index=" + index + ", length=" + length);
        }
        if (array instanceof byte[] bytes) {
            if (int32View) {
                writeInt32(bytes, offset + index * 4, ((Number) value).intValue());
                return;
            }
            bytes[offset + index] = (byte)(((Number) value).intValue() & 0xFF);
            return;
        }
        if (array instanceof char[] chars) {
            chars[offset + index] = ((Character) value).charValue();
            return;
        }
        ((T[]) array)[offset + index] = value;
    }

    /** Little-endian 4-byte read used by the int view. */
    private static int readInt32(byte[] bytes, int base) {
        return (bytes[base] & 0xFF)
            | ((bytes[base + 1] & 0xFF) << 8)
            | ((bytes[base + 2] & 0xFF) << 16)
            | ((bytes[base + 3] & 0xFF) << 24);
    }

    /** Little-endian 4-byte write used by the int view. */
    private static void writeInt32(byte[] bytes, int base, int value) {
        bytes[base] = (byte)(value & 0xFF);
        bytes[base + 1] = (byte)((value >>> 8) & 0xFF);
        bytes[base + 2] = (byte)((value >>> 16) & 0xFF);
        bytes[base + 3] = (byte)((value >>> 24) & 0xFF);
    }

    /**
     * Mirrors C# Span&lt;T&gt;.CopyTo(Span&lt;T&gt;).
     */
    public void copyTo(Span<T> destination) {
        if (destination == null) {
            throw new NullPointerException("destination");
        }
        if (destination.length < length) {
            throw new IllegalArgumentException("destination too short: " + destination.length + " < " + length);
        }
        for (int i = 0; i < length; i++) {
            destination.set(i, get(i));
        }
    }

    /**
     * Copies into a primitive char[] (C# implicit char[] → Span&lt;char&gt; at call sites).
     */
    public void copyTo(char[] destination) {
        if (destination == null) {
            throw new NullPointerException("destination");
        }
        if (destination.length < length) {
            throw new IllegalArgumentException("destination too short: " + destination.length + " < " + length);
        }
        for (int i = 0; i < length; i++) {
            destination[i] = ((Character) get(i)).charValue();
        }
    }

    /**
     * Mirrors C# Span&lt;T&gt;.Fill(T): sets every element to the given value.
     */
    public void fill(T value) {
        if (array instanceof byte[] bytes) {
            Arrays.fill(bytes, offset, offset + length, (byte)(((Number) value).intValue() & 0xFF));
            return;
        }
        if (array instanceof char[] chars) {
            Arrays.fill(chars, offset, offset + length, ((Character) value).charValue());
            return;
        }
        Arrays.fill((T[]) array, offset, offset + length, value);
    }

    public Span<T> slice(int start) {
        return slice(start, length - start);
    }

    public Span<T> slice(int start, int len) {
        if (start < 0 || len < 0 || start + len > length) {
            throw new IndexOutOfBoundsException(
                "start=" + start + ", len=" + len + ", length=" + length);
        }
        if (array instanceof byte[] bytes) {
            return new Span<>(bytes, offset + start, len);
        }
        if (array instanceof char[] chars) {
            return new Span<>(chars, offset + start, len);
        }
        return new Span<>((T[]) array, offset + start, len);
    }

    Object getArray() {
        return array;
    }

    /**
     * Materializes the slice as a primitive byte[] (elements narrowed from the
     * boxed representation). Used to pin a byte span for MemorySegment.ofArray.
     */
    public byte[] toByteArray() {
        if (array instanceof byte[] bytes) {
            return Arrays.copyOfRange(bytes, offset, offset + length);
        }
        byte[] result = new byte[length];
        for (int i = 0; i < length; i++) {
            Number value = (Number) get(i);
            result[i] = (byte)((value == null ? 0 : value.intValue()) & 0xFF);
        }
        return result;
    }

    /** C# Span&lt;T&gt;.ToArray() for char spans — materializes a primitive char[]. */
    public char[] toCharArray() {
        char[] result = new char[length];
        for (int i = 0; i < length; i++) {
            result[i] = (char) ((Character) get(i)).charValue();
        }
        return result;
    }

    /**
     * Rebuilds a Span&lt;Integer&gt; (the converter's byte-span shape) from a pinned
     * MemorySegment, mirroring C# new Span&lt;byte&gt;((byte*)ptr, length).
     */
    public static Span<Integer> fromByteSegment(java.lang.foreign.MemorySegment segment, int length) {
        Integer[] data = new Integer[length];
        for (int i = 0; i < length; i++) {
            data[i] = segment.get(java.lang.foreign.ValueLayout.JAVA_BYTE, i) & 0xFF;
        }
        return new Span<>(data);
    }

    /** Mirrors new Span&lt;char&gt;((char*)ptr, length) — reads UTF-16 char elements. */
    public static Span<Character> fromCharSegment(java.lang.foreign.MemorySegment segment, int length) {
        Character[] data = new Character[length];
        for (int i = 0; i < length; i++) {
            data[i] = segment.get(java.lang.foreign.ValueLayout.JAVA_CHAR, (long) i * 2);
        }
        return new Span<>(data);
    }

    int getOffset() {
        return offset;
    }

    public void clear() {
        Object fillValue = getDefaultValue();
        if (array instanceof byte[] bytes) {
            Arrays.fill(bytes, offset, offset + length, (byte)0);
            return;
        }
        if (array instanceof char[] chars) {
            Arrays.fill(chars, offset, offset + length, '\0');
            return;
        }
        Arrays.fill((T[]) array, offset, offset + length, (T) fillValue);
    }

    @SuppressWarnings("unchecked")
    private Object getDefaultValue() {
        // C# Span<T>.Clear() fills with default(T): 0 for numeric types, false for boolean, null for references
        if (array instanceof byte[]) return Integer.valueOf(0);
        if (array instanceof char[]) return Character.valueOf('\0');
        if (array instanceof Short[]) return Short.valueOf((short)0);
        if (array instanceof Integer[]) return java.lang.Integer.valueOf(0);
        if (array instanceof Long[]) return Long.valueOf(0L);
        if (array instanceof Byte[]) return Byte.valueOf((byte)0);
        if (array instanceof Float[]) return Float.valueOf(0.0f);
        if (array instanceof Double[]) return Double.valueOf(0.0d);
        if (array instanceof Character[]) return Character.valueOf('\0');
        if (array instanceof Boolean[]) return Boolean.FALSE;
        return null;
    }

    public T[] toArray() {
        if (array instanceof byte[] bytes) {
            @SuppressWarnings("unchecked")
            T[] copy = (T[]) new Integer[length];
            for (int i = 0; i < length; i++) {
                copy[i] = (T) java.lang.Integer.valueOf(bytes[offset + i] & 0xFF);
            }
            return copy;
        }
        if (array instanceof char[] chars) {
            @SuppressWarnings("unchecked")
            T[] copy = (T[]) new Character[length];
            for (int i = 0; i < length; i++) {
                copy[i] = (T) Character.valueOf(chars[offset + i]);
            }
            return copy;
        }
        return Arrays.copyOfRange((T[]) array, offset, offset + length);
    }

    @Override
    public String toString() {
        if (array instanceof Character[] chars) {
            StringBuilder sb = new StringBuilder(length);
            for (int i = 0; i < length; i++) {
                sb.append(chars[offset + i]);
            }
            return sb.toString();
        }
        if (array instanceof char[] chars) {
            return new String(chars, offset, length);
        }
        return super.toString();
    }
}
